const OUTFLOW_LEAK_QUAL = /(?:独家|原版|最新|绝版|完整版?|高清|首发|全网|网络|内部|私下|视频|私拍|自拍|录像|影片|照片|资源|作品|泄密|偷拍|偷录|曝光|无水印|原档)$/;
